def max_safe_concurrency(params, L, kvh, dh, S, w_b=2.0, kv_b=2.0, cap_gb=24):
    cap = cap_gb * 1e9 * 0.9
    w = params * w_b
    ov = 0.8e9
    for C in range(1, 65):
        kv = 2 * L * kvh * dh * S * C * kv_b
        act = 0.6e9 + C * 0.05e9
        if w + kv + act + ov > cap:
            return C            # 第一个触发 OOM 的并发
    return 64
